   858  static int reader(const struct reader_info *info, uint8_t *byte, uint64_t address)
   859  {
   860          if (address - info->offset >= info->size)
   861                  // out of buffer range
   862                  return -1;
   863
   864          *byte = info->code[address - info->offset];
   865
   866          return 0;
   867  }
