   869  // copy x86 detail information from internal structure to public structure
   870  static void update_pub_insn(cs_insn *pub, InternalInstruction *inter)
   871  {
   872          if (inter->vectorExtensionType != 0)
   873                  memcpy(pub->detail->x86.opcode, inter->vectorExtensionPrefix, sizeof(pub->detail->x86.opcode));
   874          else {
   875                  if (inter->twoByteEscape) {
   876                          if (inter->threeByteEscape) {
   877                                  pub->detail->x86.opcode[0] = inter->twoByteEscape;
   878                                  pub->detail->x86.opcode[1] = inter->threeByteEscape;
   879                                  pub->detail->x86.opcode[2] = inter->opcode;
   880                          } else {
   881                                  pub->detail->x86.opcode[0] = inter->twoByteEscape;
   882                                  pub->detail->x86.opcode[1] = inter->opcode;
   883                          }
   884                  } else {
   885                                  pub->detail->x86.opcode[0] = inter->opcode;
   886                  }
   887          }
   888
   889          pub->detail->x86.rex = inter->rexPrefix;
   890
   891          pub->detail->x86.addr_size = inter->addressSize;
   892
   893          pub->detail->x86.modrm = inter->orgModRM;
   894          pub->detail->x86.encoding.modrm_offset = inter->modRMOffset;
   895
   896          pub->detail->x86.sib = inter->sib;
   897          pub->detail->x86.sib_index = x86_map_sib_index(inter->sibIndex);
   898          pub->detail->x86.sib_scale = inter->sibScale;
   899          pub->detail->x86.sib_base = x86_map_sib_base(inter->sibBase);
   900
   901          pub->detail->x86.disp = inter->displacement;
   902          if (inter->consumedDisplacement) {
   903                  pub->detail->x86.encoding.disp_offset = inter->displacementOffset;
   904                  pub->detail->x86.encoding.disp_size = inter->displacementSize;
   905          }
   906
   907          pub->detail->x86.encoding.imm_offset = inter->immediateOffset;
   908          if (pub->detail->x86.encoding.imm_size == 0 && inter->immediateOffset != 0)
   909                  pub->detail->x86.encoding.imm_size = inter->immediateSize;
   910  }
