   939  // Public interface for the disassembler
   940  bool X86_getInstruction(csh ud, const uint8_t *code, size_t code_len,
   941                  MCInst *instr, uint16_t *size, uint64_t address, void *_info)
   942  {
   943          cs_struct *handle = (cs_struct *)(uintptr_t)ud;
   944          InternalInstruction insn = { 0 };
   945          struct reader_info info;
   946          int ret;
   947          bool result;
   948
   949          info.code = code;
   950          info.size = code_len;
   951          info.offset = address;
   952
   953          if (instr->flat_insn->detail) {
   954                  // instr->flat_insn->detail initialization: 3 alternatives
   955
   956                  // 1. The whole structure, this is how it's done in other arch disassemblers
   957                  // Probably overkill since cs_detail is huge because of the 36 operands of ARM
   958
   959                  //memset(instr->flat_insn->detail, 0, sizeof(cs_detail));
   960
   961                  // 2. Only the part relevant to x86
   962                  memset(instr->flat_insn->detail, 0, offsetof(cs_detail, x86) + sizeof(cs_x86));
   963
   964                  // 3. The relevant part except for x86.operands
   965                  // sizeof(cs_x86) is 0x1c0, sizeof(x86.operands) is 0x180
   966                  // marginally faster, should be okay since x86.op_count is set to 0
   967
   968                  //memset(instr->flat_insn->detail, 0, offsetof(cs_detail, x86)+offsetof(cs_x86, operands));
   969          }
   970
   971          if (handle->mode & CS_MODE_16)
   972                  ret = decodeInstruction(&insn,
   973                                  reader, &info,
   974                                  address,
   975                                  MODE_16BIT);
   976          else if (handle->mode & CS_MODE_32)
   977                  ret = decodeInstruction(&insn,
   978                                  reader, &info,
   979                                  address,
   980                                  MODE_32BIT);
   981          else
   982                  ret = decodeInstruction(&insn,
   983                                  reader, &info,
   984                                  address,
   985                                  MODE_64BIT);
   986
   987          if (ret) {
   988                  // *size = (uint16_t)(insn.readerCursor - address);
   989                  return false;
   990          } else {
   991                  *size = (uint16_t)insn.length;
   992
   993                  result = (!translateInstruction(instr, &insn)) ?  true : false;
   994                  if (result) {
   995                          unsigned Flags = X86_IP_NO_PREFIX;
   996                          instr->imm_size = insn.immSize;
   997
   998                          // copy all prefixes
   999                          instr->x86_prefix[0] = insn.prefix0;
  1000                          instr->x86_prefix[1] = insn.prefix1;
  1001                          instr->x86_prefix[2] = insn.prefix2;
  1002                          instr->x86_prefix[3] = insn.prefix3;
  1003                          instr->xAcquireRelease = insn.xAcquireRelease;
  1004
  1005                          if (handle->detail) {
  1006                                  update_pub_insn(instr->flat_insn, &insn);
  1007                          }
  1008
  1009                          if (insn.hasAdSize)
  1010                                  Flags |= X86_IP_HAS_AD_SIZE;
   620                          if (insn->sibScale != 1 ||
   621                                          (insn->sibBase == SIB_BASE_NONE && insn->mode != MODE_64BIT) ||
   622                                          (insn->sibBase != SIB_BASE_NONE &&
   623                                           insn->sibBase != SIB_BASE_ESP && insn->sibBase != SIB_BASE_RSP &&
   624                                           insn->sibBase != SIB_BASE_R12D && insn->sibBase != SIB_BASE_R12)) {
   625                                  indexReg = insn->addressSize == 4? X86_EIZ : X86_RIZ;
   626                          } else
   627                                  indexReg = 0;
   628                  }
   629
   630                  scaleAmount = insn->sibScale;
   631          } else {
   632                  switch (insn->eaBase) {
   633                          case EA_BASE_NONE:
   634                                  if (insn->eaDisplacement == EA_DISP_NONE) {
   635                                          //debug("EA_BASE_NONE and EA_DISP_NONE for ModR/M base");
   636                                          return true;
   637                                  }
   638                                  if (insn->mode == MODE_64BIT) {
   639                                          if (insn->prefix3 == 0x67)      // address-size prefix overrides RIP relative addressing
   640                                                  MCOperand_CreateReg0(mcInst, X86_EIP);
   641                                          else
   642                                                  // Section 2.2.1.6
   643                                                  MCOperand_CreateReg0(mcInst, insn->addressSize == 4 ? X86_EIP : X86_RIP);
   644                                  } else {
   645                                          MCOperand_CreateReg0(mcInst, 0);
   646                                  }
   647
   648                                  indexReg = 0;
   649                                  break;
   650                          case EA_BASE_BX_SI:
   651                                  MCOperand_CreateReg0(mcInst, X86_BX);
   652                                  indexReg = X86_SI;
   653                                  break;
   654                          case EA_BASE_BX_DI:
   655                                  MCOperand_CreateReg0(mcInst, X86_BX);
   656                                  indexReg = X86_DI;
   657                                  break;
   658                          case EA_BASE_BP_SI:
   659                                  MCOperand_CreateReg0(mcInst, X86_BP);
   660                                  indexReg = X86_SI;
   661                                  break;
   662                          case EA_BASE_BP_DI:
   663                                  MCOperand_CreateReg0(mcInst, X86_BP);
   664                                  indexReg = X86_DI;
   665                                  break;
   666                          default:
   667                                  indexReg = 0;
   668                                  switch (insn->eaBase) {
   669                                          default:
   670                                                  //debug("Unexpected eaBase");
   671                                                  return true;
   672                                                  // Here, we will use the fill-ins defined above.  However,
   673                                                  //   BX_SI, BX_DI, BP_SI, and BP_DI are all handled above and
   674                                                  //   sib and sib64 were handled in the top-level if, so they're only
   675                                                  //   placeholders to keep the compiler happy.
   676  #define ENTRY(x)                                        \
   677                                          case EA_BASE_##x:                                 \
   678                                                    MCOperand_CreateReg0(mcInst, X86_##x); break;
   679                                                  ALL_EA_BASES
   680  #undef ENTRY
   681  #define ENTRY(x) case EA_REG_##x:
   682                                                        ALL_REGS
   683  #undef ENTRY
   684                                                        //debug("A R/M memory operand may not be a register; "
   685                                                        //      "the base field must be a base.");
   686                                                        return true;
   687                                  }
   688                  }
   689
   690                  scaleAmount = 1;
   691          }
   692
   693          MCOperand_CreateImm0(mcInst, scaleAmount);
   694          MCOperand_CreateReg0(mcInst, indexReg);
   695          MCOperand_CreateImm0(mcInst, insn->displacement);
   696
   697          MCOperand_CreateReg0(mcInst, segmentRegnums[insn->segmentOverride]);
   698
   699          return false;
   700  }
